def eval_task(self, agent_responses: List[str]) -> Tuple[bool, Dict[str, Any]]:
    """Check if the agent provided relevant travel information."""
    if not agent_responses:
        return False, {"message": "No response from agent"}
    combined = " ".join(agent_responses).lower()
    if "los angeles" not in combined:
        return False, {"message": "Response does not mention Los Angeles"}
    return True, {"message": "Agent provided information about Los Angeles"}

